/**
 * Fixtures for the server suite: a throwaway SQLite file plus a helper that
 * builds one fully-populated tenant (org, four members, a project) through the
 * real repositories, so the rows under test are the rows production writes.
 *
 * Kept apart from `tests/helpers/*` — those belong to another owner.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runMigrations } from "@/server/db/migrate";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import type { PlanId } from "@/types/billing";
import type { OrgId, UserId } from "@/types/common";
import type { Actor, Role } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

export interface Tenant {
  readonly org: Organization;
  readonly project: Project;
  readonly actors: Readonly<Record<Role, Actor>>;
  readonly userIds: Readonly<Record<Role, UserId>>;
}

const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

/**
 * Points the connection at a fresh database file and migrates it. Call from
 * `beforeAll`; the returned function removes the directory again.
 *
 * A file rather than `:memory:` because `runMigrations` and the app client
 * open separate connections, and only a file is shared between the two.
 */
export async function useTemporaryDatabase(): Promise<() => void> {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-test-"));
  const path = join(dir, "taskflow.db");

  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);

  return () => {
    rmSync(dir, { recursive: true, force: true });
  };
}

/**
 * Creates one organization with a member in every role and a single project.
 * `plan` decides which quotas apply — the free plan's three seats is what the
 * invite-limit test leans on.
 */
export async function createTenant(
  slug: string,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });

  const org = await orgRepo.insertOrg(
    { name: `${slug} inc`, slug, plan },
    owner.id,
  );

  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");

  const userIds: Partial<Record<Role, UserId>> = {};
  const actors: Partial<Record<Role, Actor>> = {};

  for (const role of ROLES) {
    const user =
      role === "owner"
        ? owner
        : await userRepo.insertUser({
            email: `${role}@${slug}.test`,
            name: `${slug} ${role}`,
            passwordHash: "seed",
          });

    await memberRepo.insertMember(org.id, user.id, role, null);

    userIds[role] = user.id;
    actors[role] = { userId: user.id, orgId: org.id, role };
  }

  const project = await projectRepo.insertProject({
    orgId: org.id,
    name: `${slug} platform`,
    slug: "platform",
    key: "PLAT",
    description: null,
    visibility: "org",
    leadId: owner.id,
    color: "#6366f1",
    targetDate: null,
  });

  return {
    org,
    project,
    actors: actors as Readonly<Record<Role, Actor>>,
    userIds: userIds as Readonly<Record<Role, UserId>>,
  };
}

/** Minimal `CreateIssueInput` with the schema's defaults already applied. */
export function issueInput(
  orgId: OrgId,
  projectId: Project["id"],
  overrides: Partial<{
    title: string;
    assigneeId: UserId | null;
    dueAt: string | null;
  }> = {},
) {
  return {
    orgId,
    projectId,
    title: overrides.title ?? "Ship the thing",
    description: null,
    status: "backlog" as const,
    priority: "none" as const,
    assigneeId: (overrides.assigneeId ?? null) as UserId | null,
    parentId: null,
    estimate: null,
    dueAt: (overrides.dueAt ?? null) as never,
    labelIds: [],
  };
}
--- overdue test
/**
 * Emits `issue.overdue` exactly once per overdue issue.
 *
 * Owner C implements `@/server/jobs/overdue-issue-job`. `isOverdue()` itself is
 * covered by `tests/lib/date.test.ts`.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

const PAST = "2026-01-01T00:00:00.000Z";
const FUTURE = "2026-12-31T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

async function makeTenant(slug: string): Promise<Tenant> {
  const tenant = await createTenant(slug);
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

async function insertIssue(
  tenant: Tenant,
  overrides: Partial<{ title: string; assigneeId: (typeof tenant.userIds)["member"] | null; dueAt: string | null }>,
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, overrides),
    tenant.userIds.owner,
    number,
  );
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("jobs/overdue-issue-job", () => {
  it("selects only issues whose due date has passed", async () => {
    const tenant = await makeTenant("overdue-select");
    const overdue = await insertIssue(tenant, { title: "Late", dueAt: PAST });
    await insertIssue(tenant, { title: "Not yet", dueAt: FUTURE });

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    await runOverdueIssueJob(NOW);

    expect(seen).toEqual([overdue.id]);
  });

  it("ignores issues in a closed status", async () => {
    const tenant = await makeTenant("overdue-closed");
    const issue = await insertIssue(tenant, { title: "Closed but late", dueAt: PAST });
    await issueRepo.setIssueStatus(tenant.org.id, issue.id, "done");

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    await runOverdueIssueJob(NOW);

    expect(seen).not.toContain(issue.id);
  });

  it("ignores issues without a due date", async () => {
    const tenant = await makeTenant("overdue-no-due");
    const issue = await insertIssue(tenant, { title: "No due date", dueAt: null });

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    await runOverdueIssueJob(NOW);

    expect(seen).not.toContain(issue.id);
  });

  it("emits issue.overdue once per overdue issue", async () => {
    const tenant = await makeTenant("overdue-payload");
    const issue = await insertIssue(tenant, {
      title: "Assigned and late",
      dueAt: PAST,
      assigneeId: tenant.userIds.member,
    });

    const seen: Array<{ issueId: string; dueAt: string; assigneeId: string | null }> = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push({
          issueId: payload.issueId,
          dueAt: payload.dueAt,
          assigneeId: payload.assigneeId,
        });
      }),
    );

    const result = await runOverdueIssueJob(NOW);

    expect(seen).toHaveLength(1);
    expect(seen[0]).toEqual({
      issueId: issue.id,
      dueAt: toIsoTimestamp(new Date(PAST)),
      assigneeId: tenant.userIds.member,
    });
    expect(result.processed).toBe(1);
    expect(result.failed).toBe(0);
  });

  it("does not re-emit for an issue already reported", async () => {
    const tenant = await makeTenant("overdue-dedupe");
    const issue = await insertIssue(tenant, { title: "Still late", dueAt: PAST });

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    await runOverdueIssueJob(NOW);
    await runOverdueIssueJob(new Date(NOW.getTime() + 60_000));

    expect(seen).toEqual([issue.id]);
  });

  it("keeps each organization's issues in its own batch", async () => {
    const north = await makeTenant("overdue-north");
    const acme = await makeTenant("overdue-acme");
    const northIssue = await insertIssue(north, { title: "North late", dueAt: PAST });
    const acmeIssue = await insertIssue(acme, { title: "Acme late", dueAt: PAST });

    const seen: Array<{ orgId: string; issueId: string }> = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push({ orgId: payload.orgId, issueId: payload.issueId });
      }),
    );

    await runOverdueIssueJob(NOW);

    expect(seen).toContainEqual({ orgId: north.org.id, issueId: northIssue.id });
    expect(seen).toContainEqual({ orgId: acme.org.id, issueId: acmeIssue.id });
    for (const entry of seen) {
      if (entry.issueId === northIssue.id) expect(entry.orgId).toBe(north.org.id);
      if (entry.issueId === acmeIssue.id) expect(entry.orgId).toBe(acme.org.id);
    }
  });
});
--- doubles/id
/**
 * Test double for `@/lib/id` (owner E).
 *
 * The server suite needs ids that are valid ULIDs *and* reproducible, so a
 * failing assertion names the same row on every run. Counter-based rather than
 * random for exactly that reason.
 */
const ULID_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const ULID_LENGTH = 26;

let counter = 0;

export function newId(): string {
  counter += 1;
  return encode(counter);
}

export function isUlid(value: string): boolean {
  return (
    value.length === ULID_LENGTH &&
    [...value].every((char) => ULID_ALPHABET.includes(char.toUpperCase()))
  );
}

export function idFactory(seed: number): () => string {
  let local = seed;
  return () => {
    local += 1;
    return encode(local);
  };
}

/** Test-only: rewinds the counter so each file starts from the same ids. */
export function resetIds(): void {
  counter = 0;
}

function encode(value: number): string {
  let remaining = value;
  let out = "";

  while (out.length < ULID_LENGTH) {
    out = `${ULID_ALPHABET[remaining % 32] ?? "0"}${out}`;
    remaining = Math.floor(remaining / 32);
  }

  return out.slice(-ULID_LENGTH);
}

