/**
 * A member's out-of-office window in one workspace. While away, new
 * assignments and overdue alerts meant for the member go to `delegateUserId`
 * instead, when one is named.
 */
export interface MemberAbsence extends TenantScoped {
  readonly userId: UserId;
  readonly delegateUserId: UserId | null;
  readonly startsAt: IsoTimestamp;
  readonly endsAt: IsoTimestamp;
  readonly note: string | null;
}

/** True when `role` is at least as privileged as `atLeast`. */
export function hasRoleAtLeast(role: Role, atLeast: Role): boolean {
  return ROLE_RANK[role] >= ROLE_RANK[atLeast];
}

/** True once `at` has reached `endsAt`: the end instant itself is already back. */
export function hasEndedAt(
  absence: Pick<MemberAbsence, "endsAt">,
  at: Date,
): boolean {
  return Date.parse(absence.endsAt) <= at.getTime();
}

/** True while `at` falls inside the window: the start counts, the end does not. */
export function isAwayAt(
  absence: Pick<MemberAbsence, "startsAt" | "endsAt">,
  at: Date,
): boolean {
  return Date.parse(absence.startsAt) <= at.getTime() && !hasEndedAt(absence, at);
}

