/**
 * Out-of-office rows, one per member per workspace. Every read and write is filtered by `orgId`.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, eq } from "drizzle-orm";
import { getDb, memberAbsences } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMemberAbsence } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

export interface AbsenceWrite {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly delegateUserId: UserId | null;
  readonly startsAt: IsoTimestamp;
  readonly endsAt: IsoTimestamp;
  readonly note: string | null;
}

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/** Sets the member's absence, replacing whatever window was there before. */
export async function upsertAbsence(write: AbsenceWrite): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(memberAbsences)
    .values({ ...write, createdAt: stamp, updatedAt: stamp })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: write.delegateUserId,
        startsAt: write.startsAt,
        endsAt: write.endsAt,
        note: write.note,
        updatedAt: stamp,
      },
    })
    .returning()
    .get();

  return toMemberAbsence(row);
}

export async function deleteAbsence(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/**
 * Called when a member leaves the workspace. Their own absence goes with them,
 * and they are dropped as anyone's delegate so nothing is redirected to someone
 * who is gone. Both writes share a transaction.
 */
export async function detachMember(orgId: OrgId, userId: UserId): Promise<void> {
  const stamp = toIsoTimestamp(new Date());

  getDb().transaction((tx) => {
    tx.delete(memberAbsences)
      .where(
        and(
          orgPredicate(memberAbsences.orgId, orgId),
          eq(memberAbsences.userId, userId),
        ),
      )
      .run();

    tx.update(memberAbsences)
      .set({ delegateUserId: null, updatedAt: stamp })
      .where(
        and(
          orgPredicate(memberAbsences.orgId, orgId),
          eq(memberAbsences.delegateUserId, userId),
        ),
      )
      .run();
  });
}

