/**
 * Sets the member's out-of-office window, replacing any earlier one. Members
 * manage their own; anyone else's needs `member:update_role`. The window must
 * end after it starts, and a delegate must be another active member.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  if (Date.parse(input.endsAt) <= Date.parse(input.startsAt)) {
    throw new Error("An absence must end after it starts");
  }

  const delegateUserId = input.delegateUserId ?? null;
  if (delegateUserId === input.userId) {
    throw new Error("A member cannot be their own delegate");
  }

  const member = await requireActiveMember(input.orgId, input.userId);
  assertCanManageAbsence(actor, member);

  if (delegateUserId !== null) {
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return memberAbsenceRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note ?? null,
  });
}

/** Clears the member's absence, under the same rule as `setAbsence`. Clearing nothing is fine. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  assertCanManageAbsence(actor, member);

  await memberAbsenceRepo.deleteAbsence(orgId, userId);
}

/**
 * The member's absence while it has not yet ended, including one scheduled to
 * start later. Null once it has ended, or when none is set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:read", orgResource(orgId));
  await requireActiveMember(orgId, userId);

  const absence = await memberAbsenceRepo.findAbsence(orgId, userId);
  if (absence === null || hasEndedAt(absence, new Date())) return null;

  return absence;
}

