  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId> {
  const absence = await memberAbsenceRepo.findAbsence(orgId, userId);
  if (absence === null || absence.delegateUserId === null) return userId;

  return isAwayAt(absence, at) ? absence.delegateUserId : userId;
}

