describe("mentions while a member is away", () => {
  it("alerts a mentioned absent member and their delegate, once each", async () => {
    const tenant = await makeTenant("absence-mention");
    await memberService.setAbsence(
      tenant.actors.viewer,
      absenceInput(tenant, tenant.userIds.viewer, AWAY, tenant.userIds.admin),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mention me" }),
