    expect(result.assigneeId).toBe(tenant.userIds.viewer);
    expect(assigned).toHaveLength(1);
    expect(assigned[0]).toMatchObject({
      issueId: issue.id,
      previousAssigneeId: null,
      assigneeId: tenant.userIds.viewer,
    });
    expect(await alertHrefs(tenant, tenant.userIds.viewer, "issue_assigned")).toEqual([
      `/issues/${issue.id}`,
    ]);
    expect(await alertHrefs(tenant, tenant.userIds.member, "issue_assigned")).toEqual([]);
  });

  it("hands a new issue created for an absent member to the delegate", async () => {
    const tenant = await makeTenant("absence-assign-create");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, AWAY, tenant.userIds.viewer),
