    expect(issue.assigneeId).toBe(tenant.userIds.viewer);
  });

  it("leaves an issue with a member who takes it for themselves while away", async () => {
    const tenant = await makeTenant("absence-self-take");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, AWAY, tenant.userIds.viewer),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mine after all" }),
    );

    const { result, assigned } = await recordAssignments(() =>
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(result.assigneeId).toBe(tenant.userIds.member);
    expect(assigned[0]).toMatchObject({ assigneeId: tenant.userIds.member });

    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Created for myself",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(created.assigneeId).toBe(tenant.userIds.member);
  });

  it("does not chain: an absent delegate keeps the issue", async () => {
    const tenant = await makeTenant("absence-no-chain");
    await memberService.setAbsence(
      tenant.actors.viewer,
      absenceInput(tenant, tenant.userIds.viewer, AWAY, tenant.userIds.owner),
    );
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, AWAY, tenant.userIds.viewer),
    );

    const issue = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Stays with the first delegate",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.viewer);
  });

  it("keeps the assignee when no delegate is named", async () => {
    const tenant = await makeTenant("absence-no-delegate");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, AWAY),
    );

    const issue = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "No one to hand to",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.member);
  });

  it("does not redirect outside the window", async () => {
    const tenant = await makeTenant("absence-outside-window");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, SCHEDULED, tenant.userIds.viewer),
    );
    const scheduled = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Before the window",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(scheduled.assigneeId).toBe(tenant.userIds.member);

    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, ENDED, tenant.userIds.viewer),
    );
    const afterwards = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "After the window",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(afterwards.assigneeId).toBe(tenant.userIds.member);
  });
});

