/**
 * Out-of-office windows: who may set them, how they are read, and where
 * assignments, overdue alerts and mentions go while a member is away.
 *
 * Each test builds its own tenant so inboxes and assignees never leak between
 * cases. Keep the total under the sweep's org batch (see `listOrgIdsForRollup`).
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as memberAbsenceRepo from "@/server/repositories/member-absence-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { SetAbsenceInput } from "@/schemas/member";
import type { CommentId, IssueId, IsoTimestamp, UserId } from "@/types/common";
import type { NotificationKind } from "@/types/notification";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

type AbsenceWindow = Pick<SetAbsenceInput, "startsAt" | "endsAt">;

function at(value: string): IsoTimestamp {
  return toIsoTimestamp(new Date(value));
}

/** Covers the present, so the absence is in force for any action made now. */
const AWAY: AbsenceWindow = {
  startsAt: at("2020-01-01T00:00:00Z"),
  endsAt: at("2099-01-01T00:00:00Z"),
};

/** Already closed. */
const ENDED: AbsenceWindow = {
  startsAt: at("2020-01-01T00:00:00Z"),
  endsAt: at("2020-06-01T00:00:00Z"),
};

/** Not opened yet. */
const SCHEDULED: AbsenceWindow = {
  startsAt: at("2098-01-01T00:00:00Z"),
  endsAt: at("2099-01-01T00:00:00Z"),
};

async function makeTenant(slug: string): Promise<Tenant> {
  const tenant = await createTenant(slug);
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

function absenceInput(
  tenant: Tenant,
  userId: UserId,
  window: AbsenceWindow,
  delegateUserId: UserId | null = null,
  note: string | null = null,
): SetAbsenceInput {
  return {
    orgId: tenant.org.id,
    userId,
    delegateUserId,
    startsAt: window.startsAt,
    endsAt: window.endsAt,
    note,
  };
}

/** Runs `action` while recording every `issue.assigned` payload it publishes. */
async function recordAssignments<T>(
  action: () => Promise<T>,
): Promise<{ result: T; assigned: unknown[] }> {
  const assigned: unknown[] = [];
  const off = subscribe("issue.assigned", (payload) => {
    assigned.push(payload);
  });
  try {
    return { result: await action(), assigned };
  } finally {
    off();
  }
}

/** Issue links of the alerts of one kind sitting in a recipient's inbox. */
async function alertHrefs(
  tenant: Tenant,
  recipientId: UserId,
  kind: NotificationKind,
): Promise<string[]> {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: [kind],
    limit: 100,
    cursor: null,
  });
  return page.items.map((item) => item.href);
}

/** Publishes `comment.created` the way the comment service does, with mentions resolved. */
async function publishMention(
  tenant: Tenant,
  issueId: IssueId,
  actorId: UserId,
  mentionedUserIds: readonly UserId[],
): Promise<void> {
  await emit("comment.created", {
    orgId: tenant.org.id,
    actorId,
    occurredAt: toIsoTimestamp(new Date()),
    commentId: `cmt-${issueId}` as CommentId,
    issueId,
    mentionedUserIds,
  });
}

describe("services/member-service absences", () => {
  it("stores an absence and reads back exactly what was stored", async () => {
    const tenant = await makeTenant("absence-store");

    const stored = await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, AWAY, tenant.userIds.admin, "Parental leave"),
    );

    expect(stored).toEqual({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: AWAY.startsAt,
      endsAt: AWAY.endsAt,
      note: "Parental leave",
    });
    expect(
      await memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).toEqual(stored);
  });

  it("returns a scheduled absence that has not started yet", async () => {
    const tenant = await makeTenant("absence-scheduled");

    const stored = await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, SCHEDULED),
    );

    expect(
      await memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).toEqual(stored);
  });

  it("reads null once the absence has ended", async () => {
    const tenant = await makeTenant("absence-ended");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, ENDED),
    );

    expect(
      await memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).toBeNull();
  });

  it("replaces an earlier absence when set again, and clears it on request", async () => {
    const tenant = await makeTenant("absence-replace");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, AWAY, tenant.userIds.admin, "first"),
    );

    const replaced = await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, SCHEDULED, null, "second"),
    );
    expect(
      await memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).toEqual(replaced);
    expect(replaced).toMatchObject({ delegateUserId: null, note: "second" });

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    expect(
      await memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).toBeNull();
  });

  it("clears quietly when nothing is set", async () => {
    const tenant = await makeTenant("absence-clear-empty");

    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeUndefined();
  });

  it("rejects a window whose end is not after its start", async () => {
    const tenant = await makeTenant("absence-window");

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, tenant.userIds.member, {
          startsAt: AWAY.startsAt,
          endsAt: AWAY.startsAt,
        }),
      ),
    ).rejects.toThrow(/end after it starts/);
  });

  it("rejects a member as their own delegate", async () => {
    const tenant = await makeTenant("absence-self-delegate");

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, tenant.userIds.member, AWAY, tenant.userIds.member),
      ),
    ).rejects.toThrow(/own delegate/);
  });

  it("refuses a delegate who is not an active member of the workspace", async () => {
    const tenant = await makeTenant("absence-foreign-delegate");
    const other = await makeTenant("absence-foreign-other");

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, tenant.userIds.member, AWAY, other.userIds.admin),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("treats a user outside the workspace as not found", async () => {
    const tenant = await makeTenant("absence-outsider");
    const other = await makeTenant("absence-outsider-other");

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.setAbsence(
        tenant.actors.owner,
        absenceInput(tenant, other.userIds.member, AWAY),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("lets a member manage their own absence but not someone else's", async () => {
    const tenant = await makeTenant("absence-self-only");

    await expect(
      memberService.setAbsence(
        tenant.actors.viewer,
        absenceInput(tenant, tenant.userIds.viewer, AWAY),
      ),
    ).resolves.toMatchObject({ userId: tenant.userIds.viewer });

    await expect(
      memberService.setAbsence(
        tenant.actors.viewer,
        absenceInput(tenant, tenant.userIds.member, AWAY),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      memberService.clearAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("lets an admin set and clear anyone's absence", async () => {
    const tenant = await makeTenant("absence-admin-override");

    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant, tenant.userIds.member, AWAY),
    );
    expect(
      await memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).not.toBeNull();

    await memberService.clearAbsence(tenant.actors.admin, tenant.org.id, tenant.userIds.member);
    expect(
      await memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).toBeNull();
  });

  it("refuses an organization outside the actor's workspace on every operation", async () => {
    const tenant = await makeTenant("absence-scope");
    const other = await makeTenant("absence-scope-other");

    await expect(
      memberService.setAbsence(tenant.actors.owner, absenceInput(other, other.userIds.member, AWAY)),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.getAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.clearAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("assignments while a member is away", () => {
  it("hands an existing issue assigned to an absent member to the delegate", async () => {
    const tenant = await makeTenant("absence-assign-existing");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Hand me over" }),
    );
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, AWAY, tenant.userIds.viewer),
    );

    const { result, assigned } = await recordAssignments(() =>
      issueService.assignIssue(tenant.actors.admin, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(result.assigneeId).toBe(tenant.userIds.viewer);
    expect(assigned).toHaveLength(1);
    expect(assigned[0]).toMatchObject({
      issueId: issue.id,
      previousAssigneeId: null,
      assigneeId: tenant.userIds.viewer,
    });
    expect(await alertHrefs(tenant, tenant.userIds.viewer, "issue_assigned")).toEqual([
      `/issues/${issue.id}`,
    ]);
    expect(await alertHrefs(tenant, tenant.userIds.member, "issue_assigned")).toEqual([]);
  });

  it("hands a new issue created for an absent member to the delegate", async () => {
    const tenant = await makeTenant("absence-assign-create");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, AWAY, tenant.userIds.viewer),
    );

    const issue = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Created for the absent",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.viewer);
  });

  it("leaves an issue with a member who takes it for themselves while away", async () => {
    const tenant = await makeTenant("absence-self-take");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, AWAY, tenant.userIds.viewer),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mine after all" }),
    );

    const { result, assigned } = await recordAssignments(() =>
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(result.assigneeId).toBe(tenant.userIds.member);
    expect(assigned[0]).toMatchObject({ assigneeId: tenant.userIds.member });

    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Created for myself",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(created.assigneeId).toBe(tenant.userIds.member);
  });

  it("does not chain: an absent delegate keeps the issue", async () => {
    const tenant = await makeTenant("absence-no-chain");
    await memberService.setAbsence(
      tenant.actors.viewer,
      absenceInput(tenant, tenant.userIds.viewer, AWAY, tenant.userIds.owner),
    );
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, AWAY, tenant.userIds.viewer),
    );

    const issue = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Stays with the first delegate",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.viewer);
  });

  it("keeps the assignee when no delegate is named", async () => {
    const tenant = await makeTenant("absence-no-delegate");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, AWAY),
    );

    const issue = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "No one to hand to",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.member);
  });

  it("does not redirect outside the window", async () => {
    const tenant = await makeTenant("absence-outside-window");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, SCHEDULED, tenant.userIds.viewer),
    );
    const scheduled = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Before the window",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(scheduled.assigneeId).toBe(tenant.userIds.member);

    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, tenant.userIds.member, ENDED, tenant.userIds.viewer),
    );
    const afterwards = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "After the window",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(afterwards.assigneeId).toBe(tenant.userIds.member);
  });
});

