    ]);
    expect(await alertHrefs(tenant, tenant.userIds.admin, "comment_mention")).toEqual([
      `/issues/${issue.id}`,
    ]);
  });

  it("does not alert the comment's author, even when they are the delegate", async () => {
    const tenant = await makeTenant("absence-mention-author");
    await memberService.setAbsence(
      tenant.actors.viewer,
      absenceInput(tenant, tenant.userIds.viewer, AWAY, tenant.userIds.admin),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Written by the delegate" }),
    );

    await publishMention(tenant, issue.id, tenant.userIds.admin, [tenant.userIds.viewer]);

    expect(await alertHrefs(tenant, tenant.userIds.viewer, "comment_mention")).toEqual([
      `/issues/${issue.id}`,
    ]);
    expect(await alertHrefs(tenant, tenant.userIds.admin, "comment_mention")).toEqual([]);
  });
});

describe("absences and membership", () => {
  it("drops a removed member's absence with them", async () => {
    const tenant = await makeTenant("absence-removed-member");
    await memberService.setAbsence(
      tenant.actors.owner,
      absenceInput(tenant, tenant.userIds.member, AWAY, tenant.userIds.viewer),
    );
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!member) throw new Error("fixture member missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    expect(await memberAbsenceRepo.findAbsence(tenant.org.id, tenant.userIds.member)).toBeNull();
    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.setAbsence(
        tenant.actors.owner,
        absenceInput(tenant, tenant.userIds.member, AWAY),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("keeps an absence but drops its delegate when the delegate is removed", async () => {
    const tenant = await makeTenant("absence-removed-delegate");
    await memberService.setAbsence(
      tenant.actors.owner,
      absenceInput(tenant, tenant.userIds.admin, AWAY, tenant.userIds.viewer, "Offsite"),
    );
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture delegate missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    expect(
      await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.admin),
    ).toMatchObject({ delegateUserId: null, note: "Offsite" });

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Nobody to hand to",
        assigneeId: tenant.userIds.admin,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.admin);
  });

  it("keeps each workspace's absence to itself", async () => {
    const home = await makeTenant("absence-home");
    const away = await makeTenant("absence-away");
    // The same user belongs to both workspaces.
    await memberRepo.insertMember(away.org.id, home.userIds.member, "member", null);

    await memberService.setAbsence(
      home.actors.member,
      absenceInput(home, home.userIds.member, AWAY, home.userIds.viewer),
    );

    expect(
      await memberService.getAbsence(away.actors.owner, away.org.id, home.userIds.member),
    ).toBeNull();
    const issue = await issueService.createIssue(
      away.actors.owner,
      issueInput(away.org.id, away.project.id, { assigneeId: home.userIds.member }),
    );
    expect(issue.assigneeId).toBe(home.userIds.member);
  });
});

